import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

/**
 * TASK: Complete checksums and largestChecksum using ExecutorService.invokeAll.
 *
 * A word's checksum is the sum of its character values:
 *   "ab" -> 'a' + 'b' -> 97 + 98 -> 195
 *   ""   -> 0
 *
 * checksums(words) must:
 *   1. build one Callable<Integer> per word (each Callable computes that word's checksum),
 *   2. submit them ALL AT ONCE with invokeAll on a fixed pool of 4 threads,
 *   3. read the returned Futures with get() and collect the values IN INPUT ORDER,
 *   4. shut the pool down with shutdown() before returning.
 *
 * invokeAll blocks until every task has finished, and the returned list of
 * Futures is in the same order as the tasks you handed it -- that is what
 * keeps the results lined up with the input.
 *
 * largestChecksum(words) returns the biggest checksum in the list,
 * or -1 for an empty list.
 *
 * Example: checksums(List.of("ab", "c")) -> [195, 99], largestChecksum -> 195
 */
public class BatchTaskRunner {

    public static List<Integer> checksums(List<String> words) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        try {
            List<Callable<Integer>> tasks = new ArrayList<>();
            for (String word : words) {
                final String target = word;
                tasks.add(new Callable<Integer>() {
                    @Override
                    public Integer call() {
                        int sum = 0;
                        for (int i = 0; i < target.length(); i++) {
                            sum += target.charAt(i);
                        }
                        return sum;
                    }
                });
            }
            List<Future<Integer>> futures = pool.invokeAll(tasks);
            List<Integer> results = new ArrayList<>();
            for (Future<Integer> future : futures) {
                results.add(future.get());
            }
            return results;
        } finally {
            pool.shutdown();
        }
    }

    public static int largestChecksum(List<String> words) throws Exception {
        List<Integer> all = checksums(words);
        if (all.isEmpty()) {
            return -1;
        }
        int best = all.get(0);
        for (int value : all) {
            if (value > best) {
                best = value;
            }
        }
        return best;
    }
}
